files.content:
html {
  block-size: 100%;
  font-size: 16px;
}

body {
  display: flex;
  gap: 3rem;
  min-inline-size: 360px;
  min-block-size: 100%;
  margin: 0;
  padding: 2rem;
  color: #fff;
  font-family: 'Open Sans', sans-serif;
  background-image: url(../images/bg.jpg);
}

h1,
h2,
h3,
p {
  margin: 0;
  padding: 0;
}

.article {
  inline-size: 60%;
  margin: auto;
  padding: 2em;
  background-color: #5f0dee;
}

.article__title {
  margin-block-end: 20px;
  font-size: 2em;
}

.article__text {
  font-size: 1.2em;
}

.author-card {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 20px;
  max-inline-size: 40%;
  margin: auto;
  padding: 20px;
  color: #333;
  background-color: #6dc1fd;
}

.author-card__image {
  inline-size: 200px;
  block-size: 220px;
  border-radius: 50%;
  object-fit: cover;
  object-position: center;
}

.author-card__text {
  font-size: 1em;
}

.author-card__title {
  margin-block-end: 31px;
  font-size: 31px;
  text-transform: uppercase;
}

@media (width <= 768px) {
  html {
    font-size: 60%;

  }

  .author-card__image {
    inline-size: 50%;
    block-size: 50%;
  }
}
